// ---------- CONFIG ----------
const MY_TZ = 'Asia/Manila';
const MY_CALENDAR = 'primary';
const WORK_START = 9;        // local hour, applied to every participant
const WORK_END = 18;         // meetings must end by this local hour
const DEFAULT_DAYS = 5;
const MIN_LEAD_HOURS = 2;    // don't suggest slots starting sooner than this
// ----------------------------

const f = $json;
const title = String(f['Meeting title'] || 'Meeting').trim();
const duration = parseInt(f['Duration (minutes)'], 10) || 30;
const days = Math.min(Math.max(parseInt(f['Search next N working days'], 10) || DEFAULT_DAYS, 1), 10);

const warnings = [];
const attendees = [];
for (const lineRaw of String(f['Attendees'] || '').split(/\r?\n/)) {
  const line = lineRaw.trim();
  if (!line) continue;
  const email = (line.match(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/) || [])[0];
  if (!email) { warnings.push(`Skipped "${line}" (no email found)`); continue; }
  let tz = line.replace(email, '').replace(/[,;|]/g, ' ').trim().split(/\s+/).find(Boolean) || MY_TZ;
  if (!DateTime.now().setZone(tz).isValid) { warnings.push(`Unknown time zone "${tz}" for ${email} - used ${MY_TZ}`); tz = MY_TZ; }
  if (!attendees.some(a => a.email === email.toLowerCase())) attendees.push({ email: email.toLowerCase(), tz });
}
if (!attendees.length) throw new Error('Add at least one attendee as "email, Time/Zone" (one per line).');

// Calendar days to scan: enough to cover N working days plus weekends.
const start = $now.plus({ hours: MIN_LEAD_HOURS });
const end = $now.plus({ days: Math.ceil(days * 7 / 5) + 2 });

return [{
  json: {
    title, duration, days, attendees, warnings, agenda: String(f['Agenda / notes'] || '').trim(),
    MY_TZ, MY_CALENDAR, WORK_START, WORK_END,
    windowStart: start.toUTC().toISO(), windowEnd: end.toUTC().toISO(),
    freeBusyBody: {
      timeMin: start.toUTC().toISO(), timeMax: end.toUTC().toISO(), timeZone: 'UTC',
      items: [{ id: MY_CALENDAR }, ...attendees.map(a => ({ id: a.email }))],
    },
  },
}];

// ---------- CONFIG ----------
const STEP_MINUTES = 30;   // candidate start times every 30 minutes
const MAX_OPTIONS = 3;
const FLEX_START = 7;      // if nobody overlaps in core hours, widen to these local hours
const FLEX_END = 21;
// ----------------------------

const plan = $('Plan Search').first().json;
const cals = $json.calendars || {};
const people = [{ email: plan.MY_CALENDAR, tz: plan.MY_TZ, me: true }, ...plan.attendees];

const busy = {};
const unknown = [];
for (const p of people) {
  const c = cals[p.email];
  if (!c || (c.errors && c.errors.length)) { if (!p.me) unknown.push(p.email); busy[p.email] = []; continue; }
  busy[p.email] = (c.busy || []).map(b => [DateTime.fromISO(b.start).toMillis(), DateTime.fromISO(b.end).toMillis()]);
}

const winStart = DateTime.fromISO(plan.windowStart);
const winEnd = DateTime.fromISO(plan.windowEnd);
let t0 = winStart.startOf('hour');
while (t0 < winStart) t0 = t0.plus({ minutes: STEP_MINUTES });

function search(workStart, workEnd) {
const workDaysSeen = new Set();
const candidates = [];
for (let t = t0; t < winEnd; t = t.plus({ minutes: STEP_MINUTES })) {
  const s = t, e = t.plus({ minutes: plan.duration });
  const myDay = s.setZone(plan.MY_TZ);
  if (myDay.weekday <= 5) workDaysSeen.add(myDay.toISODate());
  if (workDaysSeen.size > plan.days) break;

  let ok = true, score = 0;
  for (const p of people) {
    const ls = s.setZone(p.tz), le = e.setZone(p.tz);
    const startH = ls.hour + ls.minute / 60, endH = le.hour + le.minute / 60 || 24;
    if (ls.weekday > 5 || ls.toISODate() !== le.toISODate() || startH < workStart || endH > workEnd) { ok = false; break; }
    const sm = s.toMillis(), em = e.toMillis();
    if (busy[p.email].some(([bs, be]) => bs < em && be > sm)) { ok = false; break; }
    const mid = (plan.WORK_START + plan.WORK_END) / 2;
    score += Math.abs((startH + endH) / 2 - mid);
  }
  if (ok) candidates.push({ s, e, score });
}
return candidates;
}

let flex = false;
let candidates = search(plan.WORK_START, plan.WORK_END);
if (!candidates.length) { candidates = search(FLEX_START, FLEX_END); flex = candidates.length > 0; }

// Pick the fairest slots, preferring different days.
candidates.sort((a, b) => a.score - b.score || a.s.toMillis() - b.s.toMillis());
const picked = [];
for (const c of candidates) {
  if (picked.length >= MAX_OPTIONS) break;
  if (!picked.some(p => p.s.setZone(plan.MY_TZ).toISODate() === c.s.setZone(plan.MY_TZ).toISODate())) picked.push(c);
}
for (const c of candidates) {
  if (picked.length >= MAX_OPTIONS) break;
  if (!picked.includes(c) && !picked.some(p => p.s < c.e && c.s < p.e)) picked.push(c);
}
picked.sort((a, b) => a.s.toMillis() - b.s.toMillis());

const short = tz => tz.split('/').pop().replace(/_/g, ' ');
const options = picked.map(c => {
  const mine = c.s.setZone(plan.MY_TZ);
  const others = [...new Set(plan.attendees.map(a => a.tz))].filter(tz => tz !== plan.MY_TZ)
    .map(tz => `${c.s.setZone(tz).toFormat('ccc h:mm a')} ${short(tz)}`);
  const label = `${mine.toFormat('ccc LLL d, h:mm a')} ${short(plan.MY_TZ)}` + (others.length ? ` | ${others.join(' | ')}` : '');
  return { label, start: c.s.toUTC().toISO(), end: c.e.toUTC().toISO() };
});

const warnings = flex ? [...plan.warnings, `No overlap inside ${plan.WORK_START}:00-${plan.WORK_END}:00 for everyone, so these slots use ${FLEX_START}:00-${FLEX_END}:00 local time`] : plan.warnings;
return [{ json: { found: options.length > 0, options, unknown, warnings, flex } }];

// ---------- CONFIG ----------
const SEND_INVITES = true;      // true = Google emails the invite to attendees
const ADD_MEET_LINK = true;
// ----------------------------
const plan = $('Plan Search').first().json;
const { options } = $('Any Slots?').first().json;
const raw = $json['Pick a time'];
const choice = Array.isArray(raw) ? raw[0] : raw;
const opt = options.find(o => o.label === choice);
if (!opt) return [{ json: { booked: false } }];

const event = {
  summary: plan.title,
  description: [plan.agenda, 'Scheduled with the n8n Time-Zone Meeting Finder.'].filter(Boolean).join('\n\n'),
  start: { dateTime: opt.start, timeZone: plan.MY_TZ },
  end: { dateTime: opt.end, timeZone: plan.MY_TZ },
  attendees: plan.attendees.map(a => ({ email: a.email })),
};
if (ADD_MEET_LINK) event.conferenceData = { createRequest: { requestId: `n8n-${$execution.id}-${Date.now()}`, conferenceSolutionKey: { type: 'hangoutsMeet' } } };
return [{ json: { booked: true, label: opt.label, event, sendUpdates: SEND_INVITES ? 'all' : 'none', calendarId: plan.MY_CALENDAR } }];
